}

static void ui_demo_force_refresh(const char *reason)
{
  if (g_ui.screen != NULL)
    {
      lv_obj_invalidate(g_ui.screen);
    }

  lv_refr_now(NULL);
  syslog(LOG_INFO, "ui_demo: refresh %s\n",
         reason == NULL ? "" : reason);
}

static int32_t ui_demo_clamp_percent(int32_t percent)
{
  if (percent < 0)
    {
      return 0;
    }

  if (percent > 100)
    {
      return 100;
    }

  return percent;
}

