  if (code == LV_EVENT_CLICKED || code == LV_EVENT_FOCUSED)
    {
      if (g_ui.wifi_keyboard != NULL)
        {
          lv_obj_clear_flag(g_ui.wifi_keyboard, LV_OBJ_FLAG_HIDDEN);
          lv_obj_move_foreground(g_ui.wifi_keyboard);
