      {
        "wifidisconnect",
        NULL
      };

      (void)wifidisconnect_main(1, disconnect_argv);
    }

  ret = wifistop_main(1, stop_argv);
#else
  (void)stop_argv;
  ret = 0;
#endif

  pthread_mutex_lock(&g_wifi_lock);
  if (generation == g_wifi.generation)
    {
      g_wifi.stop_in_progress = false;

      if (ret == 0)
        {
          g_wifi.enabled = false;
