          ui_demo_wifi_set_message_locked(
#ifdef CONFIG_LVGL_APP_UI_DEMO_WIFI_BACKEND
            "WiFi 已关闭"
#else
            "当前固件未启用 WiFi 支持"
#endif
          );
        }
      else
        {
          g_wifi.enabled = true;
          g_wifi.status = UI_DEMO_WIFI_STATUS_ERROR;
          ui_demo_wifi_set_message_locked("WiFi 关闭失败，错误码 %d", ret);
        }
