+static void ui_demo_bluetooth_copy_text(char *dst, size_t dst_len,
+                                        const char *src)
+{
+  if (dst_len == 0)
+    {
+      return;
+    }
+
+  if (src == NULL)
+    {
+      dst[0] = '\0';
+      return;
+    }
+
+  snprintf(dst, dst_len, "%s", src);
+}
