+static void ui_demo_bluetooth_set_message_locked(const char *fmt, ...)
+{
+  va_list ap;
+
+  va_start(ap, fmt);
+  vsnprintf(g_bluetooth.message, sizeof(g_bluetooth.message), fmt, ap);
+  va_end(ap);
+}
