+static bool ui_demo_bluetooth_parse_int_after(const char *line,
+                                              const char *key,
+                                              int *value)
+{
+  const char *pos;
+  char *end;
+  long parsed;
+
+  pos = strstr(line, key);
+  if (pos == NULL)
+    {
+      return false;
+    }
+
+  pos += strlen(key);
+  parsed = strtol(pos, &end, 10);
+  if (end == pos)
+    {
+      return false;
+    }
+
+  *value = (int)parsed;
+  return true;
+}
+
+static bool ui_demo_bluetooth_copy_token_after(const char *line,
+                                               const char *key,
+                                               char *dst,
+                                               size_t dst_len)
+{
+  const char *pos;
+  size_t len;
+
+  if (dst_len == 0)
+    {
+      return false;
+    }
+
+  dst[0] = '\0';
+  pos = strstr(line, key);
+  if (pos == NULL)
+    {
+      return false;
+    }
+
+  pos += strlen(key);
+  len = strcspn(pos, " \t\r\n");
+  if (len >= dst_len)
+    {
+      len = dst_len - 1;
+    }
+
+  memcpy(dst, pos, len);
+  dst[len] = '\0';
+  return len > 0;
+}
+
+static bool ui_demo_bluetooth_copy_quoted_after(const char *line,
+                                                const char *key,
+                                                char *dst,
+                                                size_t dst_len)
+{
+  const char *pos;
+  const char *end;
+  size_t len;
+
+  if (dst_len == 0)
+    {
+      return false;
+    }
+
+  dst[0] = '\0';
+  pos = strstr(line, key);
+  if (pos == NULL)
+    {
+      return false;
+    }
+
+  pos += strlen(key);
+  if (*pos != '"')
+    {
+      return false;
+    }
+
+  pos++;
+  end = strchr(pos, '"');
+  if (end == NULL)
+    {
+      return false;
+    }
+
+  len = (size_t)(end - pos);
+  if (len >= dst_len)
+    {
+      len = dst_len - 1;
+    }
+
+  memcpy(dst, pos, len);
+  dst[len] = '\0';
+  return true;
+}
+
+static bool ui_demo_bluetooth_copy_type_after(const char *line,
+                                              char *dst,
+                                              size_t dst_len)
+{
+  const char *type;
+  const char *open;
+  const char *close;
+  size_t len;
+
+  if (dst_len == 0)
+    {
+      return false;
+    }
+
+  dst[0] = '\0';
+  type = strstr(line, " type=");
+  if (type == NULL)
+    {
+      return false;
+    }
+
+  open = strchr(type, '(');
+  close = open == NULL ? NULL : strchr(open + 1, ')');
+  if (open == NULL || close == NULL || close <= open + 1)
+    {
+      return false;
+    }
+
+  len = (size_t)(close - open - 1);
+  if (len >= dst_len)
+    {
+      len = dst_len - 1;
+    }
+
+  memcpy(dst, open + 1, len);
+  dst[len] = '\0';
+  return true;
+}
