+      return ret;
+    }
+
+  pid = task_spawn("bluetoothd", bluetoothd_main, NULL, &attr, NULL, NULL);
+  posix_spawnattr_destroy(&attr);
+  if (pid < 0)
+    {
+      return pid;
+    }
+
+  pthread_mutex_lock(&g_bluetooth_lock);
+  g_bluetooth.daemon_pid = pid;
+  pthread_mutex_unlock(&g_bluetooth_lock);
+
+  return 0;
+}
