+static int ui_demo_bluetooth_spawn_scan_capture(
+  char * const argv[],
+  struct ui_demo_bluetooth_device *devices,
+  size_t *count)
+{
+  posix_spawn_file_actions_t file_actions;
+  posix_spawnattr_t attr;
+  struct pollfd pfd;
+  pid_t pid;
+  char chunk[UI_DEMO_BLUETOOTH_CAPTURE_CHUNK];
+  char line[UI_DEMO_BLUETOOTH_CAPTURE_LINE];
+  size_t line_len = 0;
+  int pipefd[2];
+  int ret;
+
+  if (devices == NULL || count == NULL)
+    {
+      return -EINVAL;
+    }
+
+  *count = 0;
+  ret = pipe(pipefd);
+  if (ret < 0)
+    {
+      return -errno;
+    }
+
+  ret = posix_spawn_file_actions_init(&file_actions);
+  if (ret != 0)
+    {
+      close(pipefd[0]);
+      close(pipefd[1]);
+      return -ret;
+    }
+
+  ret = posix_spawn_file_actions_adddup2(&file_actions, pipefd[1],
+                                         STDOUT_FILENO);
+  if (ret == 0)
+    {
+      ret = posix_spawn_file_actions_adddup2(&file_actions, pipefd[1],
+                                             STDERR_FILENO);
+    }
+
+  if (ret == 0)
+    {
+      ret = posix_spawn_file_actions_addclose(&file_actions, pipefd[0]);
+    }
+
+  if (ret == 0)
+    {
+      ret = posix_spawn_file_actions_addclose(&file_actions, pipefd[1]);
+    }
+
+  if (ret != 0)
+    {
+      posix_spawn_file_actions_destroy(&file_actions);
+      close(pipefd[0]);
+      close(pipefd[1]);
+      return -ret;
+    }
+
+  ret = ui_demo_bluetooth_init_spawn_attr(
+    &attr,
+    CONFIG_LVGL_APP_UI_DEMO_BLUETOOTH_TASK_PRIORITY,
+    CONFIG_LVGL_APP_UI_DEMO_BLUETOOTH_TASK_STACKSIZE);
+  if (ret < 0)
+    {
+      posix_spawn_file_actions_destroy(&file_actions);
+      close(pipefd[0]);
+      close(pipefd[1]);
+      return ret;
+    }
+
+  pid = task_spawn("btle", btle_main, &file_actions, &attr, argv, NULL);
+  posix_spawnattr_destroy(&attr);
+  posix_spawn_file_actions_destroy(&file_actions);
+  close(pipefd[1]);
+  if (pid < 0)
+    {
+      close(pipefd[0]);
+      return pid;
+    }
+
+  pfd.fd = pipefd[0];
+  pfd.events = POLLIN | POLLHUP;
+  pfd.revents = 0;
+
+  for (;;)
+    {
+      ssize_t nread;
+      size_t i;
+
+      ret = poll(&pfd, 1, -1);
+      if (ret < 0)
+        {
+          if (errno == EINTR)
+            {
+              continue;
+            }
+
+          ret = -errno;
+          break;
+        }
+
+      if ((pfd.revents & POLLIN) == 0 &&
+          (pfd.revents & POLLHUP) != 0)
+        {
+          ret = 0;
+          break;
+        }
+
+      nread = read(pipefd[0], chunk, sizeof(chunk));
+      if (nread < 0)
+        {
+          if (errno == EINTR || errno == EAGAIN)
+            {
+              continue;
+            }
+
+          ret = -errno;
+          break;
+        }
+
+      if (nread == 0)
+        {
+          ret = 0;
+          break;
+        }
+
+      for (i = 0; i < (size_t)nread; i++)
+        {
+          char ch = chunk[i];
+
+          if (ch == '\r')
+            {
+              continue;
+            }
+
+          if (ch == '\n')
+            {
+              line[line_len] = '\0';
+              ui_demo_bluetooth_parse_scan_line(line, devices, count);
+              line_len = 0;
+              continue;
+            }
+
+          if (line_len + 1 < sizeof(line))
+            {
+              line[line_len++] = ch;
+            }
+          else
+            {
+              line_len = 0;
+            }
+        }
+    }
+
+  if (line_len > 0)
+    {
+      line[line_len] = '\0';
+      ui_demo_bluetooth_parse_scan_line(line, devices, count);
+    }
+
+  close(pipefd[0]);
+  (void)ui_demo_bluetooth_wait_pid(pid, UI_DEMO_BLUETOOTH_WAIT_SLICE_MS);
+  return ret;
+}
+#else
+static int ui_demo_bluetooth_spawn_daemon(void)
+{
+  return -ENOSYS;
+}
+
+static int ui_demo_bluetooth_spawn_scan_capture(
+  char * const argv[],
+  struct ui_demo_bluetooth_device *devices,
+  size_t *count)
+{
+  (void)argv;
+  (void)devices;
+  (void)count;
+  return -ENOSYS;
+}
+#endif
