+static int ui_demo_bluetooth_ensure_started(void)
+{
+  char *start_argv[] =
+  {
+    "btstart",
+    NULL
+  };
+  unsigned int waited;
+  int ret;
+
+  ret = btstart_main(1, start_argv);
+  if (ret != 0)
+    {
+      return ret < 0 ? ret : -EIO;
+    }
+
+  if (ui_demo_bluetooth_btle_state() == 0)
+    {
+      return 0;
+    }
+
+  ret = ui_demo_bluetooth_spawn_daemon();
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  usleep(UI_DEMO_BLUETOOTH_DAEMON_SETTLE_US);
+  for (waited = 0; waited <= UI_DEMO_BLUETOOTH_DAEMON_WAIT_MS;
+       waited += UI_DEMO_BLUETOOTH_WAIT_SLICE_MS)
+    {
+      if (ui_demo_bluetooth_btle_state() == 0)
+        {
+          return 0;
+        }
+
+      usleep(UI_DEMO_BLUETOOTH_WAIT_SLICE_MS * 1000);
+    }
+
+  return -ETIMEDOUT;
+}
