+static int ui_demo_bluetooth_scan_entry(int argc, char *argv[])
+{
+  struct ui_demo_bluetooth_device devices[UI_DEMO_BLUETOOTH_MAX_DEVICES];
+  uint32_t generation;
+  size_t count = 0;
+  bool should_start_gatt;
+  int ret;
+  int gatt_ret = 0;
+
+  (void)argc;
+  (void)argv;
+
+  pthread_mutex_lock(&g_bluetooth_lock);
+  generation = g_bluetooth.scan_generation;
+  pthread_mutex_unlock(&g_bluetooth_lock);
+
+  memset(devices, 0, sizeof(devices));
+
+#ifdef CONFIG_LVGL_APP_UI_DEMO_BLUETOOTH_BACKEND
+  (void)ui_demo_bluetooth_stop_gatt();
+
+  ret = ui_demo_bluetooth_ensure_started();
+  if (ret == 0)
+    {
+      ret = ui_demo_bluetooth_run_scan(devices, &count);
+    }
+
+  pthread_mutex_lock(&g_bluetooth_lock);
+  should_start_gatt = generation == g_bluetooth.generation &&
+                      !g_bluetooth.stop_in_progress &&
+                      ret == 0;
+  pthread_mutex_unlock(&g_bluetooth_lock);
+
+  if (should_start_gatt)
+    {
+      gatt_ret = ui_demo_bluetooth_start_gatt();
+    }
+#else
+  ret = -ENOSYS;
+  should_start_gatt = false;
+#endif
+
+  pthread_mutex_lock(&g_bluetooth_lock);
+  if (generation == g_bluetooth.generation)
+    {
+      g_bluetooth.scan_in_progress = false;
+
+      if (ret < 0)
+        {
+          g_bluetooth.enabled = false;
+          g_bluetooth.server_running = false;
+          g_bluetooth.status = UI_DEMO_BLUETOOTH_STATUS_ERROR;
+          g_bluetooth.device_count = 0;
+          ui_demo_bluetooth_set_message_locked(
+            ret == -ENOSYS ?
+            "当前固件未启用蓝牙支持" :
+            "蓝牙扫描失败，错误码 %d",
+            ret);
+        }
+      else
+        {
+          g_bluetooth.enabled = true;
+          memcpy(g_bluetooth.devices, devices, sizeof(devices));
+          g_bluetooth.device_count = count;
+          if (gatt_ret == 0 && should_start_gatt)
+            {
+              g_bluetooth.server_running = true;
+              g_bluetooth.status = UI_DEMO_BLUETOOTH_STATUS_ADVERTISING;
+            }
+          else
+            {
+              g_bluetooth.server_running = false;
+              g_bluetooth.status = UI_DEMO_BLUETOOTH_STATUS_READY;
+            }
+
+          if (count == 0)
+            {
+              ui_demo_bluetooth_set_message_locked(
+                gatt_ret == 0 ?
+                "未扫描到蓝牙设备，GATT 服务已开启" :
+                "未扫描到蓝牙设备");
+            }
+          else
+            {
+              ui_demo_bluetooth_set_message_locked(
+                gatt_ret == 0 ?
+                "扫描完成，发现 %lu 个蓝牙设备，GATT 服务已开启" :
+                "扫描完成，发现 %lu 个蓝牙设备",
+                (unsigned long)count);
+            }
+        }
+    }
+  pthread_mutex_unlock(&g_bluetooth_lock);
+
+  ui_demo_bluetooth_notify(UI_DEMO_BLUETOOTH_EVENT_SCAN_FINISHED);
+  return ret;
+}
+
+static int ui_demo_bluetooth_stop_entry(int argc, char *argv[])
+{
+  uint32_t generation;
+  int ret = 0;
+
+  (void)argc;
+  (void)argv;
+
+  pthread_mutex_lock(&g_bluetooth_lock);
+  generation = g_bluetooth.stop_generation;
+  pthread_mutex_unlock(&g_bluetooth_lock);
+
+#ifdef CONFIG_LVGL_APP_UI_DEMO_BLUETOOTH_BACKEND
+  (void)ui_demo_bluetooth_stop_gatt();
+
+  {
+    char *stop_argv[] =
+    {
+      "btstop",
+      "--force-daemon",
+      NULL
+    };
+
+    ret = btstop_main(2, stop_argv);
+    if (ret != 0)
+      {
+        ret = ret < 0 ? ret : -EIO;
+      }
+  }
+#else
+  ret = 0;
+#endif
+
+  pthread_mutex_lock(&g_bluetooth_lock);
+  if (generation == g_bluetooth.generation)
+    {
+      g_bluetooth.stop_in_progress = false;
+      g_bluetooth.scan_in_progress = false;
+
+      if (ret == 0)
+        {
+          g_bluetooth.enabled = false;
+          g_bluetooth.server_running = false;
+          g_bluetooth.status = UI_DEMO_BLUETOOTH_STATUS_OFF;
+          g_bluetooth.device_count = 0;
+          g_bluetooth.daemon_pid = -1;
+          g_bluetooth.gatt_pid = -1;
+          ui_demo_bluetooth_set_message_locked(
+#ifdef CONFIG_LVGL_APP_UI_DEMO_BLUETOOTH_BACKEND
+            "蓝牙已关闭"
+#else
+            "当前固件未启用蓝牙支持"
+#endif
+          );
+        }
+      else
+        {
+          g_bluetooth.enabled = true;
+          g_bluetooth.status = UI_DEMO_BLUETOOTH_STATUS_ERROR;
+          ui_demo_bluetooth_set_message_locked("蓝牙关闭失败，错误码 %d",
+                                               ret);
+        }
+    }
+  pthread_mutex_unlock(&g_bluetooth_lock);
+
+  ui_demo_bluetooth_notify(UI_DEMO_BLUETOOTH_EVENT_STOP_FINISHED);
+  return ret;
+}
+
+static int ui_demo_bluetooth_create_task(
+  const char *name,
+  int (*entry)(int argc, char *argv[]))
+{
+  char *task_argv[] =
+  {
+    (char *)name,
+    NULL
+  };
+  int pid;
+
+  pid = task_create(name,
+                    CONFIG_LVGL_APP_UI_DEMO_BLUETOOTH_TASK_PRIORITY,
+                    CONFIG_LVGL_APP_UI_DEMO_BLUETOOTH_TASK_STACKSIZE,
+                    entry,
+                    task_argv);
+  if (pid < 0)
+    {
+      return errno == 0 ? -EIO : -errno;
+    }
+
+  return 0;
+}
