static int32_t ui_demo_bluetooth_signal_from_rssi(int32_t rssi)
{
  if (rssi == 0)
    {
      return 0;
    }

  if (rssi >= -35)
    {
      return 100;
    }

  if (rssi <= -95)
    {
      return 5;
    }

  return 5 + ((rssi + 95) * 95) / 60;
}

static bool ui_demo_bluetooth_parse_int_after(const char *line,
                                              const char *key,
                                              int *value)
{
  const char *pos;
  char *end;
  long parsed;

  pos = strstr(line, key);
  if (pos == NULL)
    {
      return false;
