void ui_demo_bluetooth_get_snapshot(
  struct ui_demo_bluetooth_snapshot *snapshot)
{
  if (snapshot == NULL)
    {
      return;
    }

  pthread_mutex_lock(&g_bluetooth_lock);
  snapshot->enabled = g_bluetooth.enabled;
  snapshot->scan_in_progress = g_bluetooth.scan_in_progress;
  snapshot->stop_in_progress = g_bluetooth.stop_in_progress;
  snapshot->server_running = g_bluetooth.server_running;
  snapshot->status = g_bluetooth.status;
  ui_demo_bluetooth_copy_text(snapshot->message, sizeof(snapshot->message),
                              g_bluetooth.message);
  snapshot->device_count = g_bluetooth.device_count;
  memcpy(snapshot->devices, g_bluetooth.devices, sizeof(snapshot->devices));
  pthread_mutex_unlock(&g_bluetooth_lock);
}

int ui_demo_bluetooth_start_scan(bool force_refresh)
{
  bool first_start;
  int ret;

  pthread_mutex_lock(&g_bluetooth_lock);
  if (g_bluetooth.scan_in_progress)
    {
      ui_demo_bluetooth_set_message_locked("正在扫描蓝牙，请稍候");
      pthread_mutex_unlock(&g_bluetooth_lock);
      ui_demo_bluetooth_notify(UI_DEMO_BLUETOOTH_EVENT_STATE_CHANGED);
      return -EINPROGRESS;
    }

  if (g_bluetooth.stop_in_progress)
    {
      ui_demo_bluetooth_set_message_locked("蓝牙正在关闭，请稍候");
      pthread_mutex_unlock(&g_bluetooth_lock);
      ui_demo_bluetooth_notify(UI_DEMO_BLUETOOTH_EVENT_STATE_CHANGED);
      return -EBUSY;
    }

  first_start = !g_bluetooth.enabled;
  g_bluetooth.generation++;
  g_bluetooth.enabled = true;
  g_bluetooth.scan_in_progress = true;
  g_bluetooth.status = first_start ?
                       UI_DEMO_BLUETOOTH_STATUS_STARTING :
                       UI_DEMO_BLUETOOTH_STATUS_SCANNING;
  g_bluetooth.scan_generation = g_bluetooth.generation;

  if (force_refresh || first_start || g_bluetooth.device_count == 0)
    {
      ui_demo_bluetooth_set_message_locked("正在启动并扫描蓝牙...");
    }
  else
    {
      ui_demo_bluetooth_set_message_locked("正在后台刷新蓝牙列表...");
    }
  pthread_mutex_unlock(&g_bluetooth_lock);

  ret = ui_demo_bluetooth_create_task("ui_bt_scan",
                                      ui_demo_bluetooth_scan_entry);
  if (ret < 0)
    {
      pthread_mutex_lock(&g_bluetooth_lock);
      g_bluetooth.scan_in_progress = false;
      if (first_start)
        {
          g_bluetooth.enabled = false;
        }

      g_bluetooth.status = UI_DEMO_BLUETOOTH_STATUS_ERROR;
      ui_demo_bluetooth_set_message_locked("创建蓝牙扫描任务失败：%d",
                                           ret);
      pthread_mutex_unlock(&g_bluetooth_lock);
      ui_demo_bluetooth_notify(UI_DEMO_BLUETOOTH_EVENT_SCAN_FINISHED);
      return ret;
    }

  ui_demo_bluetooth_notify(UI_DEMO_BLUETOOTH_EVENT_SCAN_STARTED);
  return 0;
}

int ui_demo_bluetooth_stop(void)
{
  int ret;

  pthread_mutex_lock(&g_bluetooth_lock);
#ifndef CONFIG_LVGL_APP_UI_DEMO_BLUETOOTH_BACKEND
  if (!g_bluetooth.enabled && !g_bluetooth.scan_in_progress)
    {
