}

static void ui_demo_bluetooth_parse_scan_line(
  const char *line,
  struct ui_demo_bluetooth_device *devices,
  size_t *count)
{
  struct ui_demo_bluetooth_device dev;
  char name[UI_DEMO_BLUETOOTH_NAME_LEN];
  int best_rssi = 0;
  int connectable = 0;

  if (line == NULL || devices == NULL || count == NULL ||
      *count >= UI_DEMO_BLUETOOTH_MAX_DEVICES ||
      strncmp(line, "btle: dev[", 10) != 0)
    {
      return;
    }

  memset(&dev, 0, sizeof(dev));
  ui_demo_bluetooth_copy_token_after(line, " addr=", dev.addr,
                                     sizeof(dev.addr));
  if (dev.addr[0] == '\0')
    {
      return;
    }

  ui_demo_bluetooth_copy_type_after(line, dev.addr_type,
                                    sizeof(dev.addr_type));
  if (dev.addr_type[0] == '\0')
    {
      ui_demo_bluetooth_copy_text(dev.addr_type, sizeof(dev.addr_type),
                                  "unknown");
    }

  if (!ui_demo_bluetooth_parse_int_after(line, " best=", &best_rssi))
    {
      ui_demo_bluetooth_parse_int_after(line, " rssi=", &best_rssi);
    }

  ui_demo_bluetooth_parse_int_after(line, " conn=", &connectable);
  dev.rssi = best_rssi;
  dev.signal = ui_demo_bluetooth_signal_from_rssi(best_rssi);
  dev.connectable = connectable != 0;

  name[0] = '\0';
  ui_demo_bluetooth_copy_quoted_after(line, " name=", name, sizeof(name));
  if (name[0] != '\0')
    {
      ui_demo_bluetooth_copy_text(dev.name, sizeof(dev.name), name);
    }
  else
    {
      ui_demo_bluetooth_copy_text(dev.name, sizeof(dev.name), dev.addr);
    }

  snprintf(dev.status, sizeof(dev.status),
           "%s  %s  RSSI %ld dBm",
           dev.addr, dev.connectable ? "可连接" : "广播",
           (long)dev.rssi);

  devices[*count] = dev;
  (*count)++;
}

static int ui_demo_bluetooth_wait_pid(pid_t pid, unsigned int wait_ms)
{
#ifdef CONFIG_SCHED_WAITPID
  unsigned int waited = 0;
  int status;
  int ret;

  while (waited <= wait_ms)
    {
      ret = waitpid(pid, &status, WNOHANG);
      if (ret == pid)
        {
          return 0;
        }

      if (ret < 0)
        {
          return errno == ECHILD || errno == ESRCH ? 0 : -errno;
        }

      usleep(UI_DEMO_BLUETOOTH_WAIT_SLICE_MS * 1000);
      waited += UI_DEMO_BLUETOOTH_WAIT_SLICE_MS;
    }

  return -ETIMEDOUT;
#else
  (void)pid;
  usleep(wait_ms * 1000);
  return 0;
#endif
}

