+static int ui_demo_bluetooth_wait_pid(pid_t pid, unsigned int wait_ms,
+                                      int *exit_code)
+{
+#ifdef CONFIG_SCHED_WAITPID
+  unsigned int waited = 0;
+  int status = 0;
+  int ret;
+
+  while (waited <= wait_ms)
+    {
+      ret = waitpid(pid, &status, WNOHANG);
+      if (ret == pid)
+        {
+          int code = 0;
+
+#ifdef WIFEXITED
+          if (WIFEXITED(status))
+            {
+              code = WEXITSTATUS(status);
+            }
+          else
+            {
+              code = status == 0 ? 0 : 1;
+            }
+#else
+          code = status == 0 ? 0 : 1;
+#endif
+
+          if (exit_code != NULL)
+            {
+              *exit_code = code;
+            }
+
+          return 0;
+        }
+
+      if (ret < 0)
+        {
+          if (errno == ECHILD || errno == ESRCH)
+            {
+              if (exit_code != NULL)
+                {
+                  *exit_code = 0;
+                }
+
+              return 0;
+            }
+
+          return -errno;
+        }
+
+      usleep(UI_DEMO_BLUETOOTH_WAIT_SLICE_MS * 1000);
+      waited += UI_DEMO_BLUETOOTH_WAIT_SLICE_MS;
+    }
+
+  return -ETIMEDOUT;
+#else
+  (void)pid;
+  usleep(wait_ms * 1000);
+  if (exit_code != NULL)
+    {
+      *exit_code = 0;
+    }
+
+  return 0;
+#endif
+}
