+static int ui_demo_bluetooth_spawn_with_pipe(
+  const char *name,
+  main_t entry,
+  char * const argv[],
+  int stacksize,
+  pid_t *pid_out,
+  int *read_fd_out)
+{
+  posix_spawn_file_actions_t file_actions;
+  posix_spawnattr_t attr;
+  int pipefd[2];
+  pid_t pid;
+  int ret;
+
+  if (pid_out == NULL || read_fd_out == NULL)
+    {
+      return -EINVAL;
+    }
+
+  ret = pipe(pipefd);
+  if (ret < 0)
+    {
+      return -errno;
+    }
+
+  ret = posix_spawn_file_actions_init(&file_actions);
+  if (ret != 0)
+    {
+      close(pipefd[0]);
+      close(pipefd[1]);
+      return -ret;
+    }
+
+  ret = posix_spawn_file_actions_adddup2(&file_actions, pipefd[1],
+                                         STDOUT_FILENO);
+  if (ret == 0)
+    {
+      ret = posix_spawn_file_actions_adddup2(&file_actions, pipefd[1],
+                                             STDERR_FILENO);
+    }
+
+  if (ret == 0)
+    {
+      ret = posix_spawn_file_actions_addclose(&file_actions, pipefd[0]);
+    }
+
+  if (ret == 0)
+    {
+      ret = posix_spawn_file_actions_addclose(&file_actions, pipefd[1]);
+    }
+
+  if (ret != 0)
+    {
+      posix_spawn_file_actions_destroy(&file_actions);
+      close(pipefd[0]);
+      close(pipefd[1]);
+      return -ret;
+    }
+
+  ret = ui_demo_bluetooth_init_spawn_attr(
+    &attr,
+    CONFIG_LVGL_APP_UI_DEMO_BLUETOOTH_TASK_PRIORITY,
+    stacksize);
+  if (ret < 0)
+    {
+      posix_spawn_file_actions_destroy(&file_actions);
+      close(pipefd[0]);
+      close(pipefd[1]);
+      return ret;
+    }
+
+  pid = task_spawn(name, entry, &file_actions, &attr, argv, NULL);
+  posix_spawnattr_destroy(&attr);
+  posix_spawn_file_actions_destroy(&file_actions);
+  close(pipefd[1]);
+  if (pid < 0)
+    {
+      close(pipefd[0]);
+      return pid;
+    }
+
+  *pid_out = pid;
+  *read_fd_out = pipefd[0];
+  return 0;
+}
