static int ui_demo_bluetooth_spawn_with_pipe(
  const char *name,
  main_t entry,
  char * const argv[],
  int stacksize,
  pid_t *pid_out,
  int *read_fd_out)
{
  posix_spawn_file_actions_t file_actions;
  posix_spawnattr_t attr;
  int pipefd[2];
  pid_t pid;
  int ret;

  if (pid_out == NULL || read_fd_out == NULL)
    {
      return -EINVAL;
    }

  ret = pipe(pipefd);
  if (ret < 0)
    {
      return -errno;
    }

  ret = posix_spawn_file_actions_init(&file_actions);
  if (ret != 0)
    {
      close(pipefd[0]);
      close(pipefd[1]);
      return -ret;
    }

  ret = posix_spawn_file_actions_adddup2(&file_actions, pipefd[1],
                                         STDOUT_FILENO);
  if (ret == 0)
    {
      ret = posix_spawn_file_actions_adddup2(&file_actions, pipefd[1],
                                             STDERR_FILENO);
    }

  if (ret == 0)
    {
      ret = posix_spawn_file_actions_addclose(&file_actions, pipefd[0]);
    }

  if (ret == 0)
    {
      ret = posix_spawn_file_actions_addclose(&file_actions, pipefd[1]);
    }

  if (ret != 0)
    {
      posix_spawn_file_actions_destroy(&file_actions);
      close(pipefd[0]);
      close(pipefd[1]);
      return -ret;
    }

  ret = ui_demo_bluetooth_init_spawn_attr(
    &attr,
    CONFIG_LVGL_APP_UI_DEMO_BLUETOOTH_TASK_PRIORITY,
    stacksize);
  if (ret < 0)
    {
      posix_spawn_file_actions_destroy(&file_actions);
      close(pipefd[0]);
      close(pipefd[1]);
      return ret;
    }

  pid = task_spawn(name, entry, &file_actions, &attr, argv, NULL);
  posix_spawnattr_destroy(&attr);
  posix_spawn_file_actions_destroy(&file_actions);
  close(pipefd[1]);
  if (pid < 0)
    {
      close(pipefd[0]);
      return pid;
    }

  *pid_out = pid;
  *read_fd_out = pipefd[0];
  return 0;
}

static int ui_demo_bluetooth_read_capture(
  int read_fd,
  pid_t pid,
  void (*line_cb)(const char *line, void *user_data),
  void *user_data)
{
  struct pollfd pfd;
  char chunk[UI_DEMO_BLUETOOTH_CAPTURE_CHUNK];
  char line[UI_DEMO_BLUETOOTH_CAPTURE_LINE];
  size_t line_len = 0;
  int ret = 0;
  int exit_code = 0;

  pfd.fd = read_fd;
  pfd.events = POLLIN | POLLHUP;
  pfd.revents = 0;

  for (;;)
    {
      ssize_t nread;
      size_t i;

      ret = poll(&pfd, 1, -1);
      if (ret < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          ret = -errno;
          break;
        }

      if ((pfd.revents & POLLIN) == 0 &&
          (pfd.revents & POLLHUP) != 0)
        {
          ret = 0;
          break;
        }

      nread = read(read_fd, chunk, sizeof(chunk));
      if (nread < 0)
        {
          if (errno == EINTR || errno == EAGAIN)
            {
              continue;
            }

          ret = -errno;
          break;
        }

      if (nread == 0)
        {
          ret = 0;
          break;
        }

      for (i = 0; i < (size_t)nread; i++)
        {
          char ch = chunk[i];

          if (ch == '\r')
            {
              continue;
            }

          if (ch == '\n')
            {
              line[line_len] = '\0';
              if (line_cb != NULL)
                {
                  line_cb(line, user_data);
                }

              line_len = 0;
              continue;
            }

          if (line_len + 1 < sizeof(line))
            {
              line[line_len++] = ch;
            }
          else
            {
              line_len = 0;
            }
        }
    }

  if (line_len > 0 && line_cb != NULL)
    {
      line[line_len] = '\0';
      line_cb(line, user_data);
    }

  close(read_fd);
  if (ret < 0)
    {
      (void)ui_demo_bluetooth_wait_pid(pid,
                                       UI_DEMO_BLUETOOTH_WAIT_SLICE_MS,
                                       NULL);
      return ret;
    }

  ret = ui_demo_bluetooth_wait_pid(pid, UI_DEMO_BLUETOOTH_CMD_WAIT_MS,
                                   &exit_code);
  if (ret < 0)
    {
      return ret;
    }

  return exit_code == 0 ? 0 : -EIO;
}
