static bool aic_ble_gap_add_adv_field(uint8_t *data, size_t data_size,
                                      size_t *pos, uint8_t type,
                                      const uint8_t *value,
                                      size_t value_len)
{
  if (*pos + value_len + 2 > data_size || value_len > 0xfe)
