   519	  void (*line_cb)(const char *line, void *user_data),
   520	  void *user_data)
   521	{
   522	  struct pollfd pfd;
   523	  char chunk[UI_DEMO_BLUETOOTH_CAPTURE_CHUNK];
   524	  char line[UI_DEMO_BLUETOOTH_CAPTURE_LINE];
   525	  size_t line_len = 0;
   526	  int ret = 0;
   527	  int exit_code = 0;
