   529	  pfd.fd = read_fd;
   530	  pfd.events = POLLIN | POLLHUP;
   531	  pfd.revents = 0;
   532	
   533	  for (;;)
   534	    {
   535	      ssize_t nread;
   536	      size_t i;
   537	
   538	      ret = poll(&pfd, 1, -1);
   539	      if (ret < 0)
   540	        {
   541	          if (errno == EINTR)
   542	            {
   543	              continue;
   544	            }
   545	
   546	          ret = -errno;
   547	          break;
   548	        }
   549	
   550	      if ((pfd.revents & POLLIN) == 0 &&
   551	          (pfd.revents & POLLHUP) != 0)
   552	        {
   553	          ret = 0;
   554	          break;
   555	        }
   556	
   557	      nread = read(read_fd, chunk, sizeof(chunk));
   558	      if (nread < 0)
   559	        {
   560	          if (errno == EINTR || errno == EAGAIN)
   561	            {
   562	              continue;
   563	            }
   564	
   565	          ret = -errno;
   566	          break;
   567	        }
   568	
   569	      if (nread == 0)
   570	        {
   571	          ret = 0;
   572	          break;
   573	        }
   574	
   575	      for (i = 0; i < (size_t)nread; i++)
   576	        {
   577	          char ch = chunk[i];
   578	
   579	          if (ch == '\r')
   580	            {
   581	              continue;
   582	            }
   583	
   584	          if (ch == '\n')
   585	            {
   586	              line[line_len] = '\0';
   587	              if (line_cb != NULL)
   588	                {
   589	                  line_cb(line, user_data);
   590	                }
   591	
   592	              line_len = 0;
   593	              continue;
   594	            }
   595	
   596	          if (line_len + 1 < sizeof(line))
   597	            {
   598	              line[line_len++] = ch;
   599	            }
   600	          else
   601	            {
   602	              line_len = 0;
   603	            }
   604	        }
   605	    }
   606	
   607	  if (line_len > 0 && line_cb != NULL)
   608	    {
   609	      line[line_len] = '\0';
   610	      line_cb(line, user_data);
   611	    }
   612	
   613	  close(read_fd);
